3	namespace App\Http\Middleware;
4	
5	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
6	use App\Services\Stripe\StripeConnectService;
7	use Closure;
8	use Illuminate\Http\Request;
9	
10	// V2: Funding gate for brand-side affiliate-invite write endpoints. The
11	// brand can't push their first invite into the wild without a card on
12	// file, because every commission payout that affiliate generates becomes
13	// the brand's funding obligation. Without this gate, the platform absorbs
14	// the float for any brand who lapses on Stripe before the first payout
15	// settles.
16	//
17	// Returns 402 Payment Required with a structured payload so the
18	// dashboard can surface the funding-gate dialog without parsing prose.
19	// Non-brand callers pass through — only brand professional types own
20	// invite endpoints, so a 402 here would be misleading for staff or
21	// affiliate JWTs that hit the route in error.
22	//
23	// Apply via route middleware: `->middleware('brand-funding-gate')`.
24	class BrandFundingGate
25	{
26	    use ResolveCurrentProfessional;
27	
28	    public function __construct(private StripeConnectService $connectService) {}
29	
30	    public function handle(Request $request, Closure $next)
31	    {
32	        $professional = $this->currentProfessional($request);
33	
34	        // Non-brand requests pass through. The route's own role check (or
35	        // policy / controller guard) is the right place to 403 for
36	        // non-brand traffic; double-rejecting here would mask the real
37	        // reason and make the response shape misleading.
38	        if (mb_strtolower(trim((string) $professional->professional_type)) !== 'brand') {
39	            return $next($request);
40	        }
41	
42	        if ($this->connectService->brandHasPaymentMethod($professional)) {
43	            return $next($request);
44	        }
45	
46	        // 402 Payment Required is the correct semantic. The payload's
47	        // `code` field is what the dashboard reads to render the
48	        // funding-gate dialog vs a generic toast.
49	        return response()->json([
50	            'message' => 'A payment method is required before sending affiliate invites.',
51	            'code' => 'brand_funding_required',
52	            'data' => [
53	                'reason' => 'no_payment_method',
54	                'connect_path' => '/account/settings?section=payments',
55	            ],
56	        ], 402);
57	    }
58	}
59

1	<?php
2	
3	namespace App\Http\Controllers\Api\Webhooks;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Billing\Plan;
7	use App\Models\Billing\Subscription;
8	use App\Models\Core\Professional\Professional;
9	use App\Services\Notifications\NotificationPublisher;
10	use App\Services\Professional\SiteProvisioningService;
11	use Carbon\Carbon;
12	use Illuminate\Http\JsonResponse;
13	use Illuminate\Http\Request;
14	use Illuminate\Support\Facades\DB;
15	use Illuminate\Support\Facades\Log;
16	use Illuminate\Support\Str;
17	use Stripe\Exception\SignatureVerificationException;
18	use Stripe\Webhook;
19	
20	// V2: Core. Processes Stripe Billing subscription lifecycle webhooks. Source of truth for subscription state.
21	class StripeWebhookController extends Controller
22	{
23	    use ValidatesStripeWebhookPayload;
24	    public function __invoke(Request $request): JsonResponse
25	    {
26	        $payload = $request->getContent();
27	        $sigHeader = $request->header('Stripe-Signature');
28	
29	        if (! $sigHeader) {
30	            return response()->json(['error' => 'Missing signature'], 400);
31	        }
32	
33	        $secret = config('services.stripe.webhook_secret');
34	
35	        if (! $secret) {
36	            return response()->json(['error' => 'No webhook secret configured'], 400);
37	        }
38	
39	        try {
40	            $event = Webhook::constructEvent($payload, $sigHeader, $secret);
41	        } catch (SignatureVerificationException) {
42	            Log::warning('Stripe billing webhook signature verification failed');
43	
44	            return response()->json(['error' => 'Invalid signature'], 400);
45	        } catch (\Exception $e) {
46	            Log::warning('Stripe billing webhook parse error', ['error' => $e->getMessage()]);
47	
48	            return response()->json(['error' => 'Invalid payload'], 400);
49	        }
50	
51	        if (! $this->validateEventStructure($event)) {
52	            return response()->json(['error' => 'Invalid payload structure'], 400);
53	        }
54	
55	        // Idempotency: atomic insert-or-skip using DB unique constraint on stripe_event_id.
56	        // This prevents race conditions where two concurrent requests pass an exists() check.
57	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
58	            'id' => Str::uuid()->toString(),
59	            'stripe_event_id' => $event->id,
60	            'event_type' => $event->type,
61	            'payload' => json_encode(json_decode($payload, true)),
62	            'processed_at' => now(),
63	        ]);
64	
65	        if ($alreadyProcessed) {
66	            return response()->json(['received' => true]);
67	        }
68	
69	        match ($event->type) {
70	            'customer.subscription.created' => $this->handleSubscriptionCreated($event->data->object, $event),
71	            'customer.subscription.updated' => $this->handleSubscriptionUpdated($event->data->object, $event),
72	            'customer.subscription.deleted' => $this->handleSubscriptionDeleted($event->data->object, $event),
73	            'invoice.paid' => $this->handleInvoicePaid($event->data->object, $event),
74	            'invoice.payment_failed' => $this->handleInvoicePaymentFailed($event->data->object, $event),
75	            default => Log::debug('Unhandled Stripe billing event', ['type' => $event->type]),
76	        };
77	
78	        return response()->json(['received' => true]);
79	    }
80	
81	    private function handleSubscriptionCreated(object $subscription, object $event): void
82	    {
83	        // Resolve professional: prefer stripe_customer_id lookup (tamper-proof),
84	        // fall back to metadata (set server-side by StripeBillingService).
85	        $stripeCustomerId = (string) ($subscription->customer ?? '');
86	        $professional = $stripeCustomerId
87	            ? Professional::where('stripe_customer_id', $stripeCustomerId)->first()
88	            : null;
89	
90	        if (! $professional) {
91	            $professionalId = $subscription->metadata?->sidest_professional_id ?? null;
92	            $professional = $professionalId ? Professional::find($professionalId) : null;
93	        }
94	
95	        if (! $professional) {
96	            Log::warning('Stripe subscription.created: could not resolve professional', [
97	                'subscription_id' => $subscription->id,
98	                'customer_id' => $stripeCustomerId,
99	                'metadata_professional_id' => $subscription->metadata?->sidest_professional_id ?? null,
100	            ]);
101	
102	            return;
103	        }
104	
105	        $priceId = $subscription->items->data[0]->price->id ?? null;
106	        $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
107	
108	        if (! $plan) {
109	            Log::error('Stripe subscription.created with unknown price — customer charged but no local subscription created. Manual reconciliation required.', [
110	                'price_id' => $priceId,
111	                'professional_id' => $professional->id,
112	                'stripe_subscription_id' => $subscription->id,
113	            ]);
114	
115	            return;
116	        }
117	
118	        DB::transaction(function () use ($professional, $plan, $subscription, $event) {
119	            // End any existing active subscription (lockForUpdate prevents deadlocks)
120	            Subscription::query()
121	                ->where('professional_id', $professional->id)
122	                ->whereNull('ended_at')
123	                ->lockForUpdate()
124	                ->update(['ended_at' => now()]);
125	
126	            // Create the new Stripe-managed subscription; stripe IDs set directly (not mass-assignable)
127	            $localSub = new Subscription([
128	                'id' => Str::uuid()->toString(),
129	                'professional_id' => $professional->id,
130	                'plan_id' => $plan->id,
131	                'provider' => 'stripe',
132	                'status' => $this->mapStripeStatus($subscription->status),
133	                'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
134	                'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
135	                'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
136	                'provider_payload' => json_decode(json_encode($event), true),
137	            ]);
138	            $localSub->stripe_customer_id = (string) $subscription->customer;
139	            $localSub->stripe_subscription_id = (string) $subscription->id;
140	            $localSub->save();
141	        });
142	
143	        Log::info('Stripe subscription created', [
144	            'professional_id' => $professional->id,
145	            'plan_key' => $plan->plan_key,
146	            'stripe_subscription_id' => $subscription->id,
147	        ]);
148	    }
149	
150	    private function handleSubscriptionUpdated(object $subscription, object $event): void
151	    {
152	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
153	
154	        if (! $localSub) {
155	            Log::debug('Stripe subscription.updated for unknown subscription', [
156	                'stripe_subscription_id' => $subscription->id,
157	            ]);
158	
159	            return;
160	        }
161	
162	        $updates = [
163	            'status' => $this->mapStripeStatus($subscription->status),
164	            'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
165	            'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
166	            'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
167	            'provider_payload' => json_decode(json_encode($event), true),
168	        ];
169	
170	        // Check if price changed (plan upgrade/downgrade)
171	        $priceId = $subscription->items->data[0]->price->id ?? null;
172	        if ($priceId) {
173	            $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
174	            if ($plan && $plan->id !== $localSub->plan_id) {
175	                $updates['plan_id'] = $plan->id;
176	            }
177	        }
178	
179	        $localSub->update($updates);
180	
181	        Log::info('Stripe subscription updated', [
182	            'subscription_id' => $localSub->id,
183	            'status' => $updates['status'],
184	        ]);
185	    }
186	
187	    private function handleSubscriptionDeleted(object $subscription, object $event): void
188	    {
189	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
190	
191	        if (! $localSub) {
192	            Log::debug('Stripe subscription.deleted for unknown subscription', [
193	                'stripe_subscription_id' => $subscription->id,
194	            ]);
195	
196	            return;
197	        }
198	
199	        $localSub->update([
200	            'status' => Subscription::STATUS_CANCELED,
201	            'ended_at' => now(),
202	            'provider_payload' => json_decode(json_encode($event), true),
203	        ]);
204	
205	        // For affiliates, fall back to free plan. Brands do NOT get a free fallback.
206	        $professional = $localSub->professional;
207	        if ($professional && $professional->professional_type !== 'brand') {
208	            app(SiteProvisioningService::class)->ensureFreeSubscription($professional);
209	        }
210	
211	        Log::info('Stripe subscription deleted', [
212	            'subscription_id' => $localSub->id,
213	            'professional_id' => $localSub->professional_id,
214	            'fallback_to_free' => $professional?->professional_type !== 'brand',
215	        ]);
216	    }
217	
218	    private function handleInvoicePaid(object $invoice, object $event): void
219	    {
220	        $stripeSubId = $invoice->subscription ?? null;
221	        if (! $stripeSubId) {
222	            return;
223	        }
224	
225	        $localSub = Subscription::where('stripe_subscription_id', $stripeSubId)->first();
226	        if (! $localSub) {
227	            return;
228	        }
229	
230	        $updates = [
231	            'provider_payload' => json_decode(json_encode($event), true),
232	        ];
233	
234	        // Reset to active if was past_due (successful retry)
235	        if ($localSub->status === Subscription::STATUS_PAST_DUE) {
236	            $updates['status'] = Subscription::STATUS_ACTIVE;
237	        }
238	
239	        // Update period dates from invoice
240	        if (isset($invoice->lines->data[0]->period)) {
241	            $period = $invoice->lines->data[0]->period;
242	            $updates['current_period_start'] = Carbon::createFromTimestamp($period->start);
243	            $updates['current_period_end'] = Carbon::createFromTimestamp($period->end);
244	        }
245	
246	        $localSub->update($updates);
247	
248	        Log::info('Stripe invoice paid', [
249	            'subscription_id' => $localSub->id,
250	            'status' => $localSub->fresh()->status,
251	        ]);
252	    }
253	
254	    private function handleInvoicePaymentFailed(object $invoice, object $event): void
255	    {
256	        $stripeSubId = $invoice->subscription ?? null;
257	        if (! $stripeSubId) {
258	            return;
259	        }
260	
261	        $localSub = Subscription::where('stripe_subscription_id', $stripeSubId)->first();
262	        if (! $localSub) {
263	            return;
264	        }
265	
266	        $localSub->update([
267	            'status' => Subscription::STATUS_PAST_DUE,
268	            'provider_payload' => json_decode(json_encode($event), true),
269	        ]);
270	
271	        // Notify the professional about the payment failure
272	        $professional = $localSub->professional;
273	        if ($professional) {
274	            app(NotificationPublisher::class)->publish(
275	                professionalId: $professional->id,
276	                frontendType: 'warning',
277	                category: 'subscriptions',
278	                title: 'Payment failed',
279	                body: 'Your subscription payment could not be processed. Please update your payment method to avoid service interruption.',
280	                dedupeKey: 'payment-failed-'.$localSub->id.'-'.now()->format('Y-m-d'),
281	                ctaUrl: '/account/billing',
282	                primaryActionLabel: 'Update Payment',
283	            );
284	        }
285	
286	        Log::warning('Stripe invoice payment failed', [
287	            'subscription_id' => $localSub->id,
288	            'professional_id' => $localSub->professional_id,
289	        ]);
290	    }
291	
292	    private function mapStripeStatus(string $stripeStatus): string
293	    {
294	        return match ($stripeStatus) {
295	            'active' => Subscription::STATUS_ACTIVE,
296	            'past_due' => Subscription::STATUS_PAST_DUE,
297	            'unpaid' => Subscription::STATUS_UNPAID,
298	            'canceled' => Subscription::STATUS_CANCELED,
299	            'incomplete' => Subscription::STATUS_INCOMPLETE,
300	            'incomplete_expired' => Subscription::STATUS_INCOMPLETE_EXPIRED,
301	            'trialing' => Subscription::STATUS_ACTIVE, // we don't use trials — map to active
302	            'paused' => Subscription::STATUS_PAUSED,
303	            default => $stripeStatus,
304	        };
305	    }
306	}
