4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Core\Professional\Professional;
7	use App\Models\Retail\CommissionPayout;
8	use App\Services\Stripe\CommissionVoidService;
9	use App\Services\Stripe\StripeConnectService;
10	use Illuminate\Http\JsonResponse;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Facades\DB;
13	use Illuminate\Support\Facades\Log;
14	use Illuminate\Support\Str;
15	use Stripe\Exception\SignatureVerificationException;
16	use Stripe\Webhook;
17	
18	// V2: Core. Processes Stripe Connect events: account updates, checkout completions, transfer status, payment intents. Drives the commission payout lifecycle.
19	class StripeConnectWebhookController extends Controller
20	{
21	    use ValidatesStripeWebhookPayload;
22	    public function __invoke(Request $request): JsonResponse
23	    {
24	        $payload = $request->getContent();
25	        $sigHeader = $request->header('Stripe-Signature');
26	
27	        if (! $sigHeader) {
28	            return response()->json(['error' => 'Missing signature'], 400);
29	        }
30	
31	        // Try both Connect and platform webhook secrets so one endpoint URL
32	        // can handle events from connected accounts and destination charges.
33	        $secrets = array_filter([
34	            config('services.stripe.connect_webhook_secret'),
35	            config('services.stripe.webhook_secret'),
36	        ]);
37	
38	        if ($secrets === []) {
39	            return response()->json(['error' => 'No webhook secret configured'], 400);
40	        }
41	
42	        $event = null;
43	        foreach ($secrets as $secret) {
44	            try {
45	                $event = Webhook::constructEvent($payload, $sigHeader, $secret);
46	                break;
47	            } catch (SignatureVerificationException) {
48	                continue;
49	            } catch (\Exception $e) {
50	                Log::warning('Stripe webhook parse error', ['error' => $e->getMessage()]);
51	
52	                return response()->json(['error' => 'Invalid payload'], 400);
53	            }
54	        }
55	
56	        if (! $event) {
57	            Log::warning('Stripe webhook signature verification failed for all configured secrets');
58	
59	            return response()->json(['error' => 'Invalid signature'], 400);
60	        }
61	
62	        if (! $this->validateEventStructure($event)) {
63	            return response()->json(['error' => 'Invalid payload structure'], 400);
64	        }
65	
66	        // Idempotency: atomic insert-or-skip on the UNIQUE stripe_event_id.
67	        // Stripe event IDs are globally unique across platform + Connect events,
68	        // so billing.webhook_events covers both this controller and StripeWebhookController.
69	        // The insert is committed before the match() dispatch: if a handler throws a 500,
70	        // Stripe's retry will see the existing row and be short-circuited here rather than
71	        // re-triggering the crashing handler. Investigate via Nightwatch if that occurs.
72	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
73	            'id' => Str::uuid()->toString(),
74	            'stripe_event_id' => $event->id,
75	            'event_type' => $event->type,
76	            'payload' => json_encode(json_decode($payload, true)),
77	            'processed_at' => now(),
78	        ]);
79	
80	        if ($alreadyProcessed) {
81	            return response()->json(['received' => true]);
82	        }
83	
84	        return $this->handleParsedEvent($event);
85	    }
86	
87	    /**
88	     * Dispatch a verified, de-duplicated Stripe Event to the appropriate handler.
89	     * Extracted from __invoke() so it can be unit-tested without HMAC signing.
90	     *
91	     * Guards account-scoped event types by verifying the HMAC-signed top-level
92	     * `event->account` field matches `data.object->id`. A mismatch means the
93	     * payload was tampered with; we reject with 400 rather than mutating records.
94	     */
95	    public function handleParsedEvent(\Stripe\Event $event): JsonResponse
96	    {
97	        // For account-scoped events, event->account is the HMAC-signed source of truth.
98	        // If data.object.id differs, reject — payload could have been tampered with
99	        // to mutate a victim account using the attacker's valid HMAC.
100	        //
101	        // account.application.* events are excluded: their data.object is an Application
102	        // (id = ca_xxx), not an Account, so the id won't match event->account by design.
103	        $accountScopedPrefixes = ['account.', 'capability.'];
104	        $isAccountScoped = collect($accountScopedPrefixes)
105	            ->contains(fn ($p) => str_starts_with($event->type, $p));
106	
107	        if ($isAccountScoped && ! str_starts_with($event->type, 'account.application.')) {
108	            $topLevelAccount = $event->account ?? null;
109	            $objectId = $event->data->object->id ?? null;
110	
111	            if ($topLevelAccount === null || $topLevelAccount !== $objectId) {
112	                Log::warning('stripe.connect.account_mismatch', [
113	                    'event_id' => $event->id,
114	                    'event_account' => $topLevelAccount,
115	                    'object_id' => $objectId,
116	                ]);
117	
118	                return response()->json(['error' => 'account_mismatch'], 400);
119	            }
120	        }
121	
122	        match ($event->type) {
123	            'account.updated' => $this->handleAccountUpdated($event->data->object),
124	            'account.application.deauthorized' => $this->handleAccountDeauthorized((string) ($event->account ?? '')),
125	            'checkout.session.completed' => $this->handleCheckoutSessionCompleted($event->data->object, (string) ($event->account ?? '')),
126	            'transfer.created' => $this->handleTransferCreated($event->data->object),
127	            'transfer.failed' => $this->handleTransferFailed($event->data->object),
128	            'transfer.reversed' => $this->handleTransferFailed($event->data->object),
129	            'payment_intent.succeeded' => $this->handlePaymentIntentSucceeded($event->data->object, (string) ($event->account ?? '')),
130	            'payment_intent.payment_failed' => $this->handlePaymentIntentFailed($event->data->object),
131	            default => Log::debug('Unhandled Stripe Connect event', ['type' => $event->type]),
132	        };
133	
134	        return response()->json(['received' => true]);
135	    }
136	
137	    private function handleCheckoutSessionCompleted(object $checkoutSession, string $connectedAccountId): void
138	    {
139	        Log::debug('Stripe checkout session completed (no-op in V2)', [
140	            'checkout_session_id' => $checkoutSession->id ?? null,
141	            'connected_account_id' => $connectedAccountId,
142	        ]);
143	    }
144	
145	    /**
146	     * Handle account.application.deauthorized — fired when an Express account owner
147	     * revokes access via their Stripe dashboard. Mark them disconnected locally so
148	     * the payout job stops targeting their account and the UI surfaces the disconnect.
149	     *
150	     * Note: event->account is the connected account ID (HMAC-signed); event->data->object
151	     * is an Application object whose id will differ. The account-scope guard is skipped
152	     * for account.application.* events for this reason.
153	     */
154	    private function handleAccountDeauthorized(string $stripeAccountId): void
155	    {
156	        if (! $stripeAccountId) {
157	            Log::warning('stripe.connect.deauthorize_missing_account');
158	
159	            return;
160	        }
161	
162	        $professional = Professional::where('stripe_connect_account_id', $stripeAccountId)->first();
163	
164	        if (! $professional) {
165	            Log::debug('Stripe account.application.deauthorized for unknown account', ['account_id' => $stripeAccountId]);
166	
167	            return;
168	        }
169	
170	        $professional->update(['stripe_connect_status' => 'disconnected']);
171	
172	        Log::info('Stripe Connect account deauthorized via dashboard', [
173	            'professional_id' => $professional->id,
174	            'account_id' => $stripeAccountId,
175	        ]);
176	    }
177	
178	    private function handleAccountUpdated(object $account): void
179	    {
180	        $professional = Professional::where('stripe_connect_account_id', $account->id)->first();
181	
182	        if (! $professional) {
183	            Log::debug('Stripe account.updated for unknown account', ['account_id' => $account->id]);
184	
185	            return;
186	        }
187	
188	        // Respect local disconnect: if the professional has soft-disconnected
189	        // the account, ignore incoming Stripe events until they explicitly
190	        // reconnect via createOnboardingLink. Prevents a late account.updated
191	        // event from silently re-activating a disconnected account.
192	        if ($professional->stripe_connect_status === 'disconnected') {
193	            Log::debug('Stripe account.updated skipped — account locally disconnected', [
194	                'professional_id' => $professional->id,
195	                'account_id' => $account->id,
196	            ]);
197	
198	            return;
199	        }
200	
201	        $status = StripeConnectService::determineAccountStatus($account);
202	
203	        if ($professional->stripe_connect_status !== $status) {
204	            $oldStatus = $professional->stripe_connect_status;
205	
206	            // Atomic: if flushHeldCommissions throws, the status update is rolled back.
207	            // The professional stays in their prior state; the next account.updated
208	            // (new event_id, bypasses idempotency) retries the full transition cleanly.
209	            DB::transaction(function () use ($professional, $status, $oldStatus) {
210	                $professional->update(['stripe_connect_status' => $status]);
211	
212	                // When an affiliate transitions to 'active', flush any held commissions
213	                // so they enter the normal payout pipeline immediately.
214	                if ($status === 'active' && $oldStatus !== 'active') {
215	                    app(CommissionVoidService::class)->flushHeldCommissions($professional);
216	                }
217	            });
218	
219	            Log::info('Stripe Connect status updated', [
220	                'professional_id' => $professional->id,
221	                'old_status' => $oldStatus,
222	                'new_status' => $status,
223	            ]);
224	        }
225	    }
226	
227	    private function handleTransferCreated(object $transfer): void
228	    {
229	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
230	
231	        if (! $payoutId) {
232	            return;
233	        }
234	
235	        Log::info('Stripe transfer created', [
236	            'transfer_id' => $transfer->id,
237	            'payout_id' => $payoutId,
238	        ]);
239	    }
240	
241	    private function handleTransferFailed(object $transfer): void
242	    {
243	        $payoutId = $transfer->metadata?->sidest_payout_id ?? null;
244	
245	        if (! $payoutId) {
246	            return;
247	        }
248	
249	        $payout = CommissionPayout::find($payoutId);
250	        if ($payout && ! in_array($payout->status, ['failed', 'completed', 'cancelled'], true)) {
251	            $payout->forceFill([
252	                'status' => 'failed',
253	                'failure_code' => 'transfer_failed_webhook',
254	                'failure_reason' => 'Transfer failed according to Stripe webhook',
255	            ])->save();
256	        }
257	
258	        Log::warning('Stripe transfer failed', [
259	            'transfer_id' => $transfer->id,
260	            'payout_id' => $payoutId,
261	        ]);
262	    }
263	
264	    private function handlePaymentIntentSucceeded(object $paymentIntent, string $connectedAccountId = ''): void
265	    {
266	        // Commission payout payment intent
267	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
268	        if (! $payoutId) {
269	            return;
270	        }
271	
272	        Log::info('Stripe payment intent succeeded for payout', [
273	            'payment_intent_id' => $paymentIntent->id,
274	            'payout_id' => $payoutId,
275	        ]);
276	    }
277	
278	    private function handlePaymentIntentFailed(object $paymentIntent): void
279	    {
280	        $payoutId = $paymentIntent->metadata?->sidest_payout_id ?? null;
281	
282	        if (! $payoutId) {
283	            return;
284	        }
285	
286	        $payout = CommissionPayout::find($payoutId);
287	        if ($payout && ! in_array($payout->status, ['failed', 'completed'])) {
288	            $payout->forceFill([
289	                'status' => 'failed',
290	                'failure_code' => 'payment_failed_webhook',
291	                'failure_reason' => $paymentIntent->last_payment_error?->message ?? 'Payment failed',
292	            ])->save();
