3	namespace App\Services\Stripe;
4	
5	use App\Models\Core\Professional\Professional;
6	use App\Models\Core\Professional\ProfessionalIntegration;
7	use App\Models\Core\Professional\WalletCurrencySwitchAudit;
8	use App\Models\Retail\BrandCommissionTopup;
9	use Illuminate\Support\Arr;
10	use Illuminate\Support\Facades\DB;
11	use Stripe\Exception\ApiErrorException;
12	use Stripe\StripeClient;
13	
14	// V2: Core. Stripe Connect Express onboarding, payment method collection, wallet management, and manual top-up checkout sessions. Required for affiliate payout flow.
15	class StripeConnectService
16	{
17	    private StripeClient $stripe;
18	
19	    public function __construct()
20	    {
21	        $this->stripe = new StripeClient(config('services.stripe.secret_key'));
22	    }
23	
24	    /**
25	     * Create a Stripe Connect Express account for a professional/influencer/brand.
26	     *
27	     * Requires country_code to be set on the professional. Without it the
28	     * account would silently default to 'AU' and Stripe would later reject
29	     * the KYC form for non-AU users. Fail fast instead so the frontend can
30	     * prompt for country before onboarding.
31	     */
32	    public function createConnectAccount(Professional $professional): string
33	    {
34	        if (! is_string($professional->country_code) || trim($professional->country_code) === '') {
35	            abort(
36	                422,
37	                'Cannot create a Stripe Connect account without a country. Please set your country on your profile before connecting Stripe.'
38	            );
39	        }
40	
41	        $account = $this->stripe->accounts->create([
42	            'type' => 'express',
43	            'country' => $this->mapCountryCode($professional->country_code),
44	            'email' => $professional->primary_email,
45	            // Affiliates are individuals/sole traders — pre-selects the individual
46	            // KYC path so Stripe doesn't prompt with a business-type selector.
47	            'business_type' => 'individual',
48	            'metadata' => [
49	                'sidest_professional_id' => $professional->id,
50	                'professional_type' => $professional->professional_type,
51	            ],
52	            'capabilities' => [
53	                'transfers' => ['requested' => true],
54	                'card_payments' => ['requested' => true],
55	            ],
56	        ], ['idempotency_key' => "acct_{$professional->id}"]);
57	
58	        $update = [
59	            'stripe_connect_account_id' => $account->id,
60	            'stripe_connect_status' => 'onboarding',
61	            'stripe_grace_period_ends_at' => $professional->stripe_grace_period_ends_at
62	                ?? now()->addDays((int) config('sidest.store.grace_period_days', 30)),
63	        ];
64	
65	        // Seed wallet currency from Shopify's shop_currency so brands with
66	        // non-AUD stores don't get locked into the AUD DB default.
67	        $shopCurrency = $this->resolveShopCurrency($professional);
68	        if ($shopCurrency) {
69	            $update['stripe_manual_balance_currency'] = $shopCurrency;
70	        }
71	
72	        $professional->update($update);
73	
74	        return $account->id;
75	    }
76	
77	    /**
78	     * Generate an onboarding link for a Connect Express account.
79	     *
80	     * If the professional previously soft-disconnected (status='disconnected'
81	     * but account_id preserved), reset their status to 'onboarding' so the
82	     * webhook handler stops skipping updates and the next account.updated
83	     * event flows through normally. Stripe KYC is preserved on the account,
84	     * so reconnecting is typically a one-click flow.
85	     */
86	    public function createOnboardingLink(Professional $professional, string $returnUrl, string $refreshUrl): string
87	    {
88	        $accountId = $professional->stripe_connect_account_id;
89	
90	        if (! $accountId) {
91	            $accountId = $this->createConnectAccount($professional);
92	        } else {
93	            if ($professional->stripe_connect_status === 'disconnected') {
94	                $professional->update(['stripe_connect_status' => 'onboarding']);
95	            }
96	
97	            // Patch business_type to 'individual' on any existing account that
98	            // hasn't finished onboarding yet. Stripe permits this update while
99	            // details_submitted is false — once submitted it's locked in.
100	            try {
101	                $existing = $this->stripe->accounts->retrieve($accountId);
102	                if (! $existing->details_submitted && $existing->business_type !== 'individual') {
103	                    $this->stripe->accounts->update($accountId, ['business_type' => 'individual']);
104	                }
105	            } catch (ApiErrorException) {
106	                // Non-fatal — continue with existing account as-is.
107	            }
108	        }
109	
110	        $link = $this->stripe->accountLinks->create([
111	            'account' => $accountId,
112	            'refresh_url' => $refreshUrl,
113	            'return_url' => $returnUrl,
114	            'type' => 'account_onboarding',
115	        ]);
116	
117	        return $link->url;
118	    }
119	
120	    /**
121	     * Check the status of a Connect account and sync it locally.
122	     *
123	     * If the professional is in the locally-disconnected state, we skip the
124	     * Stripe round-trip entirely — their account still exists at Stripe and
125	     * would return 'active', but the user has explicitly opted out. Let them
126	     * stay disconnected until they reconnect via createOnboardingLink.
127	     */
128	    public function syncAccountStatus(Professional $professional): array
129	    {
130	        $accountId = $professional->stripe_connect_account_id;
131	
132	        if (! $accountId) {
133	            return [
134	                'status' => 'not_connected',
135	                'charges_enabled' => false,
136	                'payouts_enabled' => false,
137	                'details_submitted' => false,
138	            ];
139	        }
140	
141	        if ($professional->stripe_connect_status === 'disconnected') {
142	            return [
143	                'status' => 'disconnected',
144	                'charges_enabled' => false,
145	                'payouts_enabled' => false,
146	                'details_submitted' => false,
147	            ];
148	        }
149	
150	        $account = $this->stripe->accounts->retrieve($accountId);
151	
152	        $status = self::determineAccountStatus($account);
153	
154	        if ($professional->stripe_connect_status !== $status) {
155	            $professional->update(['stripe_connect_status' => $status]);
156	        }
157	
158	        return [
159	            'status' => $status,
160	            'charges_enabled' => (bool) $account->charges_enabled,
161	            'payouts_enabled' => (bool) $account->payouts_enabled,
162	            'details_submitted' => (bool) $account->details_submitted,
163	            'requirements' => $account->requirements?->currently_due ?? [],
164	        ];
165	    }
166	
167	    /**
168	     * Get the Stripe Express dashboard login link for a connected account.
169	     */
170	    public function createDashboardLink(Professional $professional): ?string
171	    {
172	        $accountId = $professional->stripe_connect_account_id;
173	
174	        if (! $accountId || $professional->stripe_connect_status !== 'active') {
175	            return null;
176	        }
177	
178	        try {
179	            $link = $this->stripe->accounts->createLoginLink($accountId);
180	
181	            return $link->url;
182	        } catch (ApiErrorException) {
183	            return null;
184	        }
185	    }
186	
187	    /**
188	     * Soft-disconnect a professional's Stripe Connect account.
189	     *
190	     * We preserve the stripe_connect_account_id so reconnection reuses the
191	     * existing Express account — no Stripe orphan accumulation, no lost KYC
192	     * data for the affiliate, reconnection is a one-click flow. Express
193	     * doesn't support a clean "reject/delete" API call for accounts with
194	     * history, so this local-flag approach is the canonical pattern.
195	     *
196	     * The payout service already guards on stripe_connect_status === 'active',
197	     * so disconnected affiliates don't receive payouts. The webhook handler
198	     * skips account.updated events for disconnected accounts to prevent
199	     * late Stripe events from silently re-activating them.
200	     */
201	    public function disconnectAccount(Professional $professional): void
202	    {
203	        $professional->update([
204	            'stripe_connect_status' => 'disconnected',
205	        ]);
206	    }
207	
208	    /**
209	     * Create a Stripe Customer for a brand so we can charge them for commissions.
210	     */
211	    public function createCustomer(Professional $brand): string
212	    {
213	        $customer = $this->stripe->customers->create([
214	            'email' => $brand->primary_email,
215	            'name' => $brand->display_name,
216	            'metadata' => [
217	                'sidest_professional_id' => $brand->id,
218	                'professional_type' => $brand->professional_type,
219	            ],
220	        ], ['idempotency_key' => "customer_{$brand->id}"]);
221	
222	        $brand->update([
223	            'stripe_customer_id' => $customer->id,
224	        ]);
225	
226	        return $customer->id;
227	    }
228	
229	    /**
230	     * Legacy SetupIntent path (kept for compatibility).
231	     */
232	    public function createSetupIntent(Professional $brand): array
233	    {
234	        $customerId = $brand->stripe_customer_id;
235	
236	        if (! $customerId) {
237	            $customerId = $this->createCustomer($brand);
238	        }
239	
240	        $setupIntent = $this->stripe->setupIntents->create([
241	            'customer' => $customerId,
242	            'payment_method_types' => ['card', 'au_becs_debit'],
243	            'metadata' => [
244	                'sidest_professional_id' => $brand->id,
245	            ],
246	        ]);
247	
248	        return [
249	            'client_secret' => $setupIntent->client_secret,
250	            'setup_intent_id' => $setupIntent->id,
251	        ];
252	    }
253	
254	    /**
255	     * Stripe Checkout hosted setup flow for collecting a reusable payment method.
256	     */
257	    public function createPaymentMethodSetupCheckoutSession(
258	        Professional $brand,
259	        string $successUrl,
260	        string $cancelUrl,
261	    ): array {
262	        $customerId = $brand->stripe_customer_id;
263	
264	        if (! $customerId) {
265	            $customerId = $this->createCustomer($brand);
266	        }
267	
268	        $session = $this->stripe->checkout->sessions->create([
269	            'mode' => 'setup',
