308	        $sessionCustomerId = is_string($session->customer)
309	            ? $session->customer
310	            : ($session->customer->id ?? null);
311	
312	        if ($brand->stripe_customer_id && $sessionCustomerId && $brand->stripe_customer_id !== $sessionCustomerId) {
313	            throw new \RuntimeException('Setup session customer does not match account customer.');
314	        }
315	
316	        if (! $brand->stripe_customer_id && $sessionCustomerId) {
317	            $brand->update(['stripe_customer_id' => $sessionCustomerId]);
318	            $brand->refresh();
319	        }
320	
321	        $setupIntentId = is_string($session->setup_intent)
322	            ? $session->setup_intent
323	            : ($session->setup_intent->id ?? null);
324	
325	        if (! $setupIntentId) {
326	            throw new \RuntimeException('Setup session missing setup intent.');
327	        }
328	
329	        $setupIntent = $this->stripe->setupIntents->retrieve($setupIntentId, [
330	            'expand' => ['payment_method'],
