481	    /**
482	     * Confirm a completed top-up Checkout session and credit the brand balance.
483	     * Idempotent by checkout session id.
484	     */
485	    public function confirmManualTopUpCheckoutSession(Professional $brand, string $sessionId): array
486	    {
487	        $existing = BrandCommissionTopup::query()
488	            ->where('stripe_checkout_session_id', $sessionId)
489	            ->first();
490	
491	        if ($existing) {
492	            $brand->refresh();
493	
494	            return [
495	                'status' => 'already_applied',
496	                'balance_cents' => (int) ($brand->stripe_manual_balance_cents ?? 0),
497	                'currency_code' => strtoupper((string) ($brand->stripe_manual_balance_currency ?: 'AUD')),
498	                'topup_id' => $existing->id,
499	            ];
500	        }
501	
502	        $session = $this->stripe->checkout->sessions->retrieve($sessionId);
503	
504	        if (($session->mode ?? null) !== 'payment') {
505	            throw new \RuntimeException('Checkout session is not a payment session.');
506	        }
507	
508	        if (($session->payment_status ?? null) !== 'paid') {
509	            throw new \RuntimeException('Top-up payment is not completed yet.');
510	        }
511	
512	        $metadataProId = $session->metadata?->sidest_professional_id ?? null;
513	        if ($metadataProId && $metadataProId !== $brand->id) {
514	            throw new \RuntimeException('Top-up session does not belong to this account.');
515	        }
516	
517	        $purpose = $session->metadata?->purpose ?? null;
518	        if ($purpose !== 'brand_commission_topup') {
519	            throw new \RuntimeException('Invalid top-up session purpose.');
520	        }
521	
522	        $amountCents = (int) ($session->amount_total ?? 0);
523	        if ($amountCents <= 0) {
524	            throw new \RuntimeException('Top-up amount is invalid.');
525	        }
526	
527	        $currency = strtoupper((string) ($session->currency ?: ($brand->stripe_manual_balance_currency ?: 'AUD')));
528	        $paymentIntentId = is_string($session->payment_intent)
529	            ? $session->payment_intent
530	            : ($session->payment_intent->id ?? null);
531	
532	        return DB::transaction(function () use ($brand, $sessionId, $paymentIntentId, $amountCents, $currency) {
533	            $lockedBrand = Professional::query()
534	                ->whereKey($brand->id)
535	                ->lockForUpdate()
536	                ->firstOrFail();
537	
538	            $existingTopup = BrandCommissionTopup::query()
539	                ->where('stripe_checkout_session_id', $sessionId)
540	                ->first();
541	
542	            if ($existingTopup) {
543	                return [
544	                    'status' => 'already_applied',
545	                    'balance_cents' => (int) ($lockedBrand->stripe_manual_balance_cents ?? 0),
546	                    'currency_code' => strtoupper((string) ($lockedBrand->stripe_manual_balance_currency ?: 'AUD')),
547	                    'topup_id' => $existingTopup->id,
548	                ];
549	            }
550	
551	            $currentBalance = (int) ($lockedBrand->stripe_manual_balance_cents ?? 0);
552	            $currentCurrency = strtoupper((string) ($lockedBrand->stripe_manual_balance_currency ?: $currency));
553	
554	            if ($currentCurrency !== $currency && $currentBalance > 0) {
555	                throw new \RuntimeException(
556	                    sprintf(
557	                        'Top-up currency %s does not match existing wallet currency %s.',
558	                        $currency,
559	                        $currentCurrency,
560	                    )
561	                );
562	            }
563	
564	            $currencyChanged = $currentCurrency !== $currency;
565	
566	            if ($currencyChanged) {
567	                $lockedBrand->stripe_manual_balance_currency = $currency;
568	            }
569	
570	            $lockedBrand->stripe_manual_balance_cents = $currentBalance + $amountCents;
571	            $lockedBrand->save();
572	
573	            $topup = BrandCommissionTopup::create([
574	                'brand_professional_id' => $lockedBrand->id,
575	                'stripe_checkout_session_id' => $sessionId,
576	                'stripe_payment_intent_id' => $paymentIntentId,
577	                'amount_cents' => $amountCents,
578	                'currency_code' => $currency,
579	                'status' => 'completed',
580	            ]);
581	
582	            if ($currencyChanged) {
583	                WalletCurrencySwitchAudit::create([
584	                    'professional_id' => $lockedBrand->id,
585	                    'previous_currency' => $currentCurrency,
586	                    'new_currency' => $currency,
587	                    'actor_type' => WalletCurrencySwitchAudit::ACTOR_TYPE_SYSTEM,
588	                    'topup_id' => $topup->id,
589	                    'metadata' => ['trigger' => 'top_up_empty_balance'],
590	                ]);
591	            }
592	
593	            return [
594	                'status' => 'applied',
595	                'balance_cents' => (int) $lockedBrand->stripe_manual_balance_cents,
596	                'currency_code' => strtoupper((string) $lockedBrand->stripe_manual_balance_currency),
597	                'topup_id' => $topup->id,
598	            ];
599	        });
600	    }
