20	// V2: Core. Processes Stripe Billing subscription lifecycle webhooks. Source of truth for subscription state.
21	class StripeWebhookController extends Controller
22	{
23	    use ValidatesStripeWebhookPayload;
24	    public function __invoke(Request $request): JsonResponse
25	    {
26	        $payload = $request->getContent();
27	        $sigHeader = $request->header('Stripe-Signature');
28	
29	        if (! $sigHeader) {
30	            return response()->json(['error' => 'Missing signature'], 400);
31	        }
32	
33	        $secret = config('services.stripe.webhook_secret');
34	
35	        if (! $secret) {
36	            return response()->json(['error' => 'No webhook secret configured'], 400);
37	        }
38	
39	        try {
40	            $event = Webhook::constructEvent($payload, $sigHeader, $secret);
41	        } catch (SignatureVerificationException) {
42	            Log::warning('Stripe billing webhook signature verification failed');
43	
44	            return response()->json(['error' => 'Invalid signature'], 400);
45	        } catch (\Exception $e) {
46	            Log::warning('Stripe billing webhook parse error', ['error' => $e->getMessage()]);
47	
48	            return response()->json(['error' => 'Invalid payload'], 400);
49	        }
50	
51	        if (! $this->validateEventStructure($event)) {
52	            return response()->json(['error' => 'Invalid payload structure'], 400);
53	        }
54	
55	        // Idempotency: atomic insert-or-skip using DB unique constraint on stripe_event_id.
56	        // This prevents race conditions where two concurrent requests pass an exists() check.
57	        $alreadyProcessed = ! DB::table('billing.webhook_events')->insertOrIgnore([
58	            'id' => Str::uuid()->toString(),
59	            'stripe_event_id' => $event->id,
60	            'event_type' => $event->type,
61	            'payload' => json_encode(json_decode($payload, true)),
62	            'processed_at' => now(),
63	        ]);
64	
65	        if ($alreadyProcessed) {
66	            return response()->json(['received' => true]);
67	        }
68	
69	        match ($event->type) {
70	            'customer.subscription.created' => $this->handleSubscriptionCreated($event->data->object, $event),
71	            'customer.subscription.updated' => $this->handleSubscriptionUpdated($event->data->object, $event),
72	            'customer.subscription.deleted' => $this->handleSubscriptionDeleted($event->data->object, $event),
73	            'invoice.paid' => $this->handleInvoicePaid($event->data->object, $event),
74	            'invoice.payment_failed' => $this->handleInvoicePaymentFailed($event->data->object, $event),
75	            default => Log::debug('Unhandled Stripe billing event', ['type' => $event->type]),
76	        };
77	
78	        return response()->json(['received' => true]);
79	    }
