81	    private function handleSubscriptionCreated(object $subscription, object $event): void
82	    {
83	        // Resolve professional: prefer stripe_customer_id lookup (tamper-proof),
84	        // fall back to metadata (set server-side by StripeBillingService).
85	        $stripeCustomerId = (string) ($subscription->customer ?? '');
86	        $professional = $stripeCustomerId
87	            ? Professional::where('stripe_customer_id', $stripeCustomerId)->first()
88	            : null;
89	
90	        if (! $professional) {
91	            $professionalId = $subscription->metadata?->sidest_professional_id ?? null;
92	            $professional = $professionalId ? Professional::find($professionalId) : null;
93	        }
94	
95	        if (! $professional) {
96	            Log::warning('Stripe subscription.created: could not resolve professional', [
97	                'subscription_id' => $subscription->id,
98	                'customer_id' => $stripeCustomerId,
99	                'metadata_professional_id' => $subscription->metadata?->sidest_professional_id ?? null,
100	            ]);
101	
102	            return;
103	        }
104	
105	        $priceId = $subscription->items->data[0]->price->id ?? null;
106	        $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
107	
108	        if (! $plan) {
109	            Log::error('Stripe subscription.created with unknown price — customer charged but no local subscription created. Manual reconciliation required.', [
110	                'price_id' => $priceId,
111	                'professional_id' => $professional->id,
112	                'stripe_subscription_id' => $subscription->id,
113	            ]);
114	
115	            return;
116	        }
117	
118	        DB::transaction(function () use ($professional, $plan, $subscription, $event) {
119	            // End any existing active subscription (lockForUpdate prevents deadlocks)
120	            Subscription::query()
121	                ->where('professional_id', $professional->id)
122	                ->whereNull('ended_at')
123	                ->lockForUpdate()
124	                ->update(['ended_at' => now()]);
125	
126	            // Create the new Stripe-managed subscription; stripe IDs set directly (not mass-assignable)
127	            $localSub = new Subscription([
128	                'id' => Str::uuid()->toString(),
129	                'professional_id' => $professional->id,
130	                'plan_id' => $plan->id,
131	                'provider' => 'stripe',
132	                'status' => $this->mapStripeStatus($subscription->status),
133	                'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
134	                'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
135	                'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
136	                'provider_payload' => json_decode(json_encode($event), true),
137	            ]);
138	            $localSub->stripe_customer_id = (string) $subscription->customer;
139	            $localSub->stripe_subscription_id = (string) $subscription->id;
140	            $localSub->save();
141	        });
142	
143	        Log::info('Stripe subscription created', [
144	            'professional_id' => $professional->id,
145	            'plan_key' => $plan->plan_key,
146	            'stripe_subscription_id' => $subscription->id,
147	        ]);
148	    }
