150	    private function handleSubscriptionUpdated(object $subscription, object $event): void
151	    {
152	        $localSub = Subscription::where('stripe_subscription_id', $subscription->id)->first();
153	
154	        if (! $localSub) {
155	            Log::debug('Stripe subscription.updated for unknown subscription', [
156	                'stripe_subscription_id' => $subscription->id,
157	            ]);
158	
159	            return;
160	        }
161	
162	        $updates = [
163	            'status' => $this->mapStripeStatus($subscription->status),
164	            'current_period_start' => Carbon::createFromTimestamp($subscription->current_period_start),
165	            'current_period_end' => Carbon::createFromTimestamp($subscription->current_period_end),
166	            'cancel_at_period_end' => $subscription->cancel_at_period_end ?? false,
167	            'provider_payload' => json_decode(json_encode($event), true),
168	        ];
169	
170	        // Check if price changed (plan upgrade/downgrade)
171	        $priceId = $subscription->items->data[0]->price->id ?? null;
172	        if ($priceId) {
173	            $plan = Plan::where('stripe_price_id', $priceId)->where('is_active', true)->first();
174	            if ($plan && $plan->id !== $localSub->plan_id) {
175	                $updates['plan_id'] = $plan->id;
176	            }
177	        }
178	
179	        $localSub->update($updates);
180	
181	        Log::info('Stripe subscription updated', [
182	            'subscription_id' => $localSub->id,
183	            'status' => $updates['status'],
184	        ]);
185	    }
