5	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
6	use App\Services\Stripe\StripeConnectService;
7	use Closure;
8	use Illuminate\Http\Request;
9	
10	// V2: Funding gate for brand-side affiliate-invite write endpoints. The
11	// brand can't push their first invite into the wild without a card on
12	// file, because every commission payout that affiliate generates becomes
13	// the brand's funding obligation. Without this gate, the platform absorbs
14	// the float for any brand who lapses on Stripe before the first payout
15	// settles.
16	//
17	// Returns 402 Payment Required with a structured payload so the
18	// dashboard can surface the funding-gate dialog without parsing prose.
19	// Non-brand callers pass through — only brand professional types own
20	// invite endpoints, so a 402 here would be misleading for staff or
21	// affiliate JWTs that hit the route in error.
22	//
23	// Apply via route middleware: `->middleware('brand-funding-gate')`.
24	class BrandFundingGate
25	{
26	    use ResolveCurrentProfessional;
27	
28	    public function __construct(private StripeConnectService $connectService) {}
29	
30	    public function handle(Request $request, Closure $next)
31	    {
32	        $professional = $this->currentProfessional($request);
33	
34	        // Non-brand requests pass through. The route's own role check (or
35	        // policy / controller guard) is the right place to 403 for
36	        // non-brand traffic; double-rejecting here would mask the real
37	        // reason and make the response shape misleading.
38	        if (mb_strtolower(trim((string) $professional->professional_type)) !== 'brand') {
39	            return $next($request);
40	        }
41	
42	        if ($this->connectService->brandHasPaymentMethod($professional)) {
43	            return $next($request);
44	        }
45	
46	        // 402 Payment Required is the correct semantic. The payload's
47	        // `code` field is what the dashboard reads to render the
48	        // funding-gate dialog vs a generic toast.
49	        return response()->json([
50	            'message' => 'A payment method is required before sending affiliate invites.',
51	            'code' => 'brand_funding_required',
52	            'data' => [
53	                'reason' => 'no_payment_method',
54	                'connect_path' => '/account/settings?section=payments',
55	            ],
56	        ], 402);
57	    }
58	}
